<template>
  <PageContainer title="分析档案" description="保存每次量化与模型分析，支持按股票和报告类型追溯">
    <template #actions><el-button :disabled="!selected.length" type="danger" plain @click="removeSelected">删除所选</el-button><el-button :loading="loading" @click="load">刷新</el-button><el-button type="primary" @click="$router.push('/agent')">发起分析</el-button></template>
    <section class="data-table-card">
      <div class="filter-bar"><el-input v-model="symbol" clearable placeholder="股票代码" @keyup.enter="search"/><el-select v-model="reportType" clearable placeholder="报告类型"><el-option label="个股分析" value="ANALYZE_STOCK"/><el-option label="知识问答" value="ASK_WITH_RAG"/><el-option label="回测复盘" value="REVIEW_BACKTEST"/></el-select><el-button @click="search">查询</el-button></div>
      <div class="table-scroll-x"><el-table :data="items" v-loading="loading" empty-text="暂无分析档案，请先发起一次智能体分析" @selection-change="selected=$event">
        <el-table-column type="selection" width="48"/><el-table-column label="生成时间" width="180"><template #default="{row}">{{formatTime(row.created_at)}}</template></el-table-column><el-table-column prop="symbol" label="股票" width="100"/><el-table-column label="类型" width="120"><template #default="{row}">{{reportTypeLabel(String(row.report_type||''))}}</template></el-table-column><el-table-column prop="summary" label="报告摘要" min-width="330" show-overflow-tooltip/><el-table-column label="引擎" min-width="180"><template #default="{row}">{{row.provider_code==='local-rules'?'本地量化引擎':`${row.provider_code||'本地'} / ${row.model||'规则模型'}`}}</template></el-table-column><el-table-column label="证据完整度" width="120"><template #default="{row}">{{toPercent(row.evidence_completeness)}}</template></el-table-column><el-table-column label="风险" width="100"><template #default="{row}"><RiskTag :value="String(row.risk_level||'UNKNOWN')"/></template></el-table-column><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button link type="primary" @click="$router.push(`/agent/reports/${row.id}`)">查看</el-button><el-button link type="danger" @click="removeOne(row)">删除</el-button></template></el-table-column>
      </el-table></div>
      <el-pagination v-if="total>pageSize" v-model:current-page="page" :page-size="pageSize" :total="total" layout="prev, pager, next, total" @current-change="load"/>
    </section><DisclaimerAlert/>
  </PageContainer>
</template>
<script setup lang="ts">
import{onMounted,ref}from'vue';import{ElMessage,ElMessageBox}from'element-plus';import PageContainer from'@/components/common/PageContainer.vue';import DisclaimerAlert from'@/components/common/DisclaimerAlert.vue';import RiskTag from'@/components/common/RiskTag.vue';import{agentApi}from'@/api/agent';import{formatTime}from'@/utils/time';import type{AgentReport}from'@/types/agent'
const items=ref<AgentReport[]>([]),selected=ref<AgentReport[]>([]),total=ref(0),loading=ref(false),symbol=ref(''),reportType=ref(''),page=ref(1),pageSize=20
const load=async()=>{loading.value=true;try{const data=await agentApi.reports({symbol:symbol.value.trim(),report_type:reportType.value,limit:pageSize,offset:(page.value-1)*pageSize});items.value=data.items||[];total.value=data.total||0}finally{loading.value=false}}
const search=()=>{page.value=1;load()};const toPercent=(v:unknown)=>`${(Math.max(0,Math.min(1,Number(v)||0))*100).toFixed(0)}%`;const reportTypeLabel=(v:string)=>({ANALYZE_STOCK:'个股分析',ASK_WITH_RAG:'知识问答',REVIEW_BACKTEST:'回测复盘',REVIEW_PAPER_ACCOUNT:'账户复盘'}[v]||v||'量化分析')
const removeOne=async(row:AgentReport)=>{if(!row.id)return ElMessage.warning('该分析档案缺少有效编号');await ElMessageBox.confirm('删除后无法在分析档案中恢复，关联模型用量记录仍会保留。','删除分析档案',{type:'warning'});await agentApi.removeReport(row.id);ElMessage.success('分析档案已删除');await load()}
const removeSelected=async()=>{const ids=selected.value.map(v=>Number(v.id||0)).filter(v=>v>0);if(!ids.length)return;await ElMessageBox.confirm(`确认删除所选 ${ids.length} 份分析档案？`,'批量删除',{type:'warning'});const result=await agentApi.removeReports(ids);ElMessage.success(`已删除 ${result.deleted_count} 份分析档案`);await load()};onMounted(load)
</script>
<style scoped>.filter-bar{display:flex;gap:10px;margin-bottom:14px}.filter-bar .el-input,.filter-bar .el-select{width:180px}.el-pagination{margin-top:16px;justify-content:flex-end}@media(max-width:640px){.filter-bar{display:grid;grid-template-columns:1fr 1fr}.filter-bar .el-input,.filter-bar .el-select{width:100%}}</style>
